import SwiftUI
struct Card<Content: View>: View { @ViewBuilder var content: Content; var body: some View { content.padding(16).frame(maxWidth: .infinity, alignment: .leading).background(.background).clipShape(RoundedRectangle(cornerRadius: 16)).shadow(color: .black.opacity(0.04), radius: 8, y: 3) } }
struct Header: View { let summary: PortfolioSummary; var body: some View { VStack(alignment: .leading, spacing: 8) { HStack { Text("我的投资").font(.title3.bold()); Spacer(); Text(Date.now, format: .dateTime.year().month().day()).font(.caption) }; Text("总资产（元）").font(.caption).foregroundStyle(.white.opacity(0.7)); Text(summary.total, format: .number.precision(.fractionLength(2))).font(.system(size: 34, weight: .bold)); Text("▲ 今日 +1,286.40（+0.45%）").font(.subheadline).foregroundStyle(.green) }.foregroundStyle(.white).padding(20).background(LinearGradient(colors: [.init(red: .1, green: .16, blue: .27), .blue.opacity(0.65)], startPoint: .topLeading, endPoint: .bottomTrailing)) }
}
